double GmsMobExpPerKill(int level) {
  if (level < 1 ||
      level > static_cast<int>(sizeof(kExpPerKill) / sizeof(kExpPerKill[0]))) {
    return 0.0;
  }
  return kExpPerKill[level - 1];
}

